\pset pager off
\echo === Q3-1 blind-spot test: gappers (gap>=10, price>=5) per scan day by market-cap bucket, distinct tickers
SELECT scan_date, count(DISTINCT ticker) FILTER (WHERE market_cap IS NULL) cap_null, count(DISTINCT ticker) FILTER (WHERE market_cap < 500e6) cap_lt500m, count(DISTINCT ticker) FILTER (WHERE market_cap >= 500e6) cap_ge500m, count(DISTINCT ticker) total FROM mi_ep_scan_log WHERE scan_date >= '2026-10-12' AND gap_pct >= 10 AND prev_close >= 5 GROUP BY 1 ORDER BY 1;
\echo === Q3-1b same, but how the cap_null gappers were stamped (stage), 10-22 and 10-23 and ran days
SELECT scan_date, reject_stage, count(DISTINCT ticker) names FROM mi_ep_scan_log WHERE scan_date >= '2026-10-19' AND gap_pct >= 10 AND prev_close >= 5 AND market_cap IS NULL GROUP BY 1,2 ORDER BY 1,2;
\echo === Q3-2 live alerts this week with scan-log market cap (is any live alert sub-500M?)
SELECT a.id, a.ticker, a.alert_date, a.score_tier, to_char(a.detected_at AT TIME ZONE 'America/New_York','HH24:MI:SS') det_et, to_char(a.created_at AT TIME ZONE 'America/New_York','HH24:MI:SS') cre_et, (SELECT round(min(s.market_cap)/1e6) FROM mi_ep_scan_log s WHERE s.ticker=a.ticker AND s.scan_date=a.alert_date) min_cap_m FROM mi_ep_alerts a WHERE a.alert_date >= '2026-10-12' ORDER BY a.id;
\echo === Q3-3 live trades since 10-08: status, skip reason, timing
SELECT id, ticker, alert_date, signal_type, account_mode, status, left(skip_reason,90) skip, entry_attempt, to_char(created_at AT TIME ZONE 'America/New_York','MM-DD HH24:MI:SS') created_et, to_char(filled_at AT TIME ZONE 'America/New_York','MM-DD HH24:MI:SS') filled_et, round(entry_price::numeric,2) entry FROM mi_live_trades WHERE id >= 415 ORDER BY id;
\echo === Q3-4 judge rows 10-19 07:20 (truncated / divergence-failed): which ticker?
SELECT id, to_char(created_at AT TIME ZONE 'America/New_York','MM-DD HH24:MI:SS') t_et, event_type, left(summary,200) s, left(detail,300) d FROM mi_audit_log WHERE event_type IN ('judge_verdict_truncated','judge_divergence_check_failed') AND created_at >= '2026-10-12 04:00+00' ORDER BY id;
\echo === Q3-5 any scan/grade error-ish audit events 09:25-09:50 ET this week and last (counts by type)
SELECT event_type, count(*) FROM mi_audit_log WHERE created_at >= '2026-10-12 04:00+00' AND (created_at AT TIME ZONE 'America/New_York')::time BETWEEN '09:25' AND '09:50' AND (event_type ILIKE '%error%' OR event_type ILIKE '%fail%' OR event_type ILIKE '%timeout%' OR event_type ILIKE '%late%' OR event_type ILIKE '%skip%') GROUP BY 1 ORDER BY 1;
\echo === Q3-6 lane graded sub-ORB: the lane ticks that fell in 09:30-09:45 ET (lane grading concurrent with live ORB window), per day
SELECT to_char(created_at AT TIME ZONE 'America/New_York','YYYY-MM-DD') d, string_agg(to_char(created_at AT TIME ZONE 'America/New_York','HH24:MI')||':'||(detail::jsonb->>'candidates')||'c/'||(detail::jsonb->>'graded')||'g', ' ' ORDER BY id) ticks FROM mi_audit_log WHERE event_type='lowcap_paper_lane_tick' AND (created_at AT TIME ZONE 'America/New_York')::time BETWEEN '09:28' AND '09:46' GROUP BY 1 ORDER BY 1;
\echo === Q3-7 tick audit rows vs scan ticks: for each lane-day, scan ticks on which a cap-only name existed vs lane tick rows
SELECT s.scan_date, count(DISTINCT s.scan_time_et) FILTER (WHERE strpos(s.filter_reason,'filter:mcap_too_small')>0) scan_ticks_with_cap_only, (SELECT count(*) FROM mi_audit_log a WHERE a.event_type='lowcap_paper_lane_tick' AND (a.created_at AT TIME ZONE 'America/New_York')::date = s.scan_date) lane_tick_rows FROM mi_ep_scan_log s WHERE s.scan_date >= '2026-10-12' GROUP BY 1 ORDER BY 1;
